@page "/apply"
@rendermode InteractiveServer
@using sv_44532c859b4744d3befb6a367afd3e3e.Models
@using sv_44532c859b4744d3befb6a367afd3e3e.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@_stepNames[stepIndex]</div>
        </div>
        @if (i < _stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo()
            break;
        case 1:
            @RenderWorkHistory()
            break;
        case 2:
            @RenderReferences()
            break;
        case 3:
            @RenderCoverLetter()
            break;
        case 4:
            @RenderReviewSubmit()
            break;
    }
</div>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep = 0;
    private string _errorMessage = string.Empty;
    private bool _isSubmitting = false;
    private int? _submittedApplicationId = null;

    // Step 1 - Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 - Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string _coverLetter = string.Empty;
    private const int CoverLetterMaxChars = 2000;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (step < _currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName))
                { _errorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                { _errorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                { _errorMessage = "Phone is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                { _errorMessage = "Address is required."; return false; }
                return true;
            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { _errorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { _errorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                    { _errorMessage = "Start date is required for all entries."; return false; }
                }
                return true;
            case 2:
                foreach (var reference in _references)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name))
                    { _errorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Relationship))
                    { _errorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Email))
                    { _errorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Phone))
                    { _errorMessage = "Phone is required for all references."; return false; }
                }
                return true;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                { _errorMessage = "Cover letter is required."; return false; }
                return true;
            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (_workEntries.Count > 1)
            _workEntries.Remove(entry);
    }

    private void AddReference()
    {
