+                                <input type="checkbox" class="form-check-input" @bind="entry.IsCurrent" id="@($"current-{i}")" />
+                                <label class="form-check-label" for="@($"current-{i}")">Currently working here</label>
+                            </div>
+                        </div>
+                    </div>
+                    <div class="mb-2">
+                        <label class="form-label">Description</label>
+                        <textarea class="form-control" @bind="entry.Description" rows="3" placeholder="Describe your responsibilities"></textarea>
+                    </div>
+                </div>
+            }
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>;
+
+    RenderFragment RenderReferences() =>
+        @<div class="form-section">
+            <h3>References</h3>
+            @for (int i = 0; i < _references.Count; i++)
+            {
+                var reference = _references[i];
+                <div class="card mb-3 p-3">
+                    <div class="d-flex justify-content-between align-items-center mb-2">
+                        <h5>Reference @(i + 1)</h5>
+                        @if (_references.Count > 2)
+                        {
+                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
+                        }
+                    </div>
+                    <div class="row mb-2">
+                        <div class="col-md-6">
+                            <label class="form-label">Name *</label>
+                            <input type="text" class="form-control" @bind="reference.Name" placeholder="Reference name" />
+                        </div>
+                        <div class="col-md-6">
+                            <label class="form-label">Relationship *</label>
+                            <input type="text" class="form-control" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
+                        </div>
+                    </div>
+                    <div class="row mb-2">
+                        <div class="col-md-6">
+                            <label class="form-label">Email *</label>
+                            <input type="email" class="form-control" @bind="reference.Email" placeholder="Email address" />
+                        </div>
+                        <div class="col-md-6">
+                            <label class="form-label">Phone *</label>
+                            <input type="tel" class="form-control" @bind="reference.Phone" placeholder="Phone number" />
+                        </div>
+                    </div>
+                </div>
+            }
+            @if (_references.Count < 3)
+            {
+                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
+            }
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>;
+
+    RenderFragment RenderCoverLetter() =>
+        @<div class="form-section">
+            <h3>Cover Letter</h3>
+            <div class="mb-3">
+                <textarea class="form-control" @bind="_coverLetter" rows="12" placeholder="Write your cover letter here..." maxlength="@CoverLetterMaxChars"></textarea>
+                <div class="form-text text-end">@_coverLetter.Length / @CoverLetterMaxChars characters</div>
+            </div>
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>;
+
+    RenderFragment RenderReviewSubmit() =>
+        @<div class="form-section">
+            @if (_submittedApplicationId.HasValue)
+            {
+                <div class="text-center py-5">
+                    <h2 class="text-success">&#10003; Application Submitted!</h2>
+                    <p class="lead">Your application ID is: <strong>@_submittedApplicationId</strong></p>
+                    <p>Thank you for applying. We will review your application and get back to you soon.</p>
+                </div>
+            }
+            else
+            {
+                <h3>Review & Submit</h3>
+
+                <div class="card mb-3 p-3">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Personal Information</h5>
+                        <button class="btn btn-link btn-sm" @onclick="() => NavigateToStep(0)">Edit</button>
+                    </div>
+                    <dl class="row mb-0">
+                        <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
+                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
+                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
+                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
+                    </dl>
+                </div>
+
+                <div class="card mb-3 p-3">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Work History</h5>
+                        <button class="btn btn-link btn-sm" @onclick="() => NavigateToStep(1)">Edit</button>
+                    </div>
+                    @foreach (var entry in _workEntries)
+                    {
+                        <div class="mb-2 ps-2 border-start border-3">
+                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                            <small>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
+                            @if (!string.IsNullOrWhiteSpace(entry.Description))
+                            {
+                                <p class="mb-0 mt-1">@entry.Description</p>
+                            }
+                        </div>
+                    }
+                </div>
+
+                <div class="card mb-3 p-3">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>References</h5>
+                        <button class="btn btn-link btn-sm" @onclick="() => NavigateToStep(2)">Edit</button>
+                    </div>
+                    @foreach (var reference in _references)
+                    {
+                        <div class="mb-2 ps-2 border-start border-3">
+                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                            <small>@reference.Email | @reference.Phone</small>
+                        </div>
+                    }
+                </div>
+
+                <div class="card mb-3 p-3">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Cover Letter</h5>
+                        <button class="btn btn-link btn-sm" @onclick="() => NavigateToStep(3)">Edit</button>
+                    </div>
+                    <p style="white-space: pre-wrap;">@_coverLetter</p>
+                </div>
+
+                <div class="d-flex justify-content-between">
+                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                        @if (_isSubmitting)
+                        {
+                            <span class="spinner-border spinner-border-sm me-2"></span>
+                        }
+                        Submit Application
+                    </button>
+                </div>
+            }
+        </div>;
+}
+
